  announcement: {
    icon: '📢',
    label: 'Pengumuman',
    color: () => C.blue
  },
  assignment: {
    icon: '📋',
    label: 'Tugasan',
    color: () => C.orange
  },
  general: {
    icon: '💬',
    label: 'Perbincangan',
    color: () => C.textMuted
  }
